  );

  const answered = GATE_CHECKS.filter((check) => !blockingCheckIds.has(check.id)).length;
  const total = GATE_CHECKS.length;

  let summary = `${result.verdict} ${answered}/${total}`;

  if (result.verdict === 'BLOCK' && blockingCheckIds.size > 0) {
    const blockingIds = GATE_CHECKS
      .filter((check) => blockingCheckIds.has(check.id))
      .map((check) => check.id)
      .join(', ');
    summary += `: ${blockingIds}`;
  }

  return summary;
}

